#!/usr/bin/env node
// v10 Phase A.3 citation-strings generator (spec-v10.md §3.3).
//
// Reads docs/citation-discipline.md, parses every per-tile source-stamp
// table under a `### calc-*.js` heading, and emits the structured
// JSON to docs/citation-strings.generated.json.
//
// Exit codes:
//   0  generated file written (or unchanged).
//   1  parse error in citation-discipline.md.
//
// CLI flags:
//   --check   parse only; fail (exit 1) if generated file would differ
//             from what is on disk. Used by `npm run lint`.
//   --emit    parse and write to disk. Default when no flag is given.
//
// The generator is deterministic so `--check` is a reliable
// in-sync gate.

import { readFile, writeFile, readdir } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { existsSync } from "node:fs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SRC = resolve(ROOT, "docs", "citation-discipline.md");
const OUT = resolve(ROOT, "docs", "citation-strings.generated.json");

const MODE = process.argv.includes("--check") ? "check" : "emit";
// --stdout writes the generated bytes to stdout instead of overwriting the
// committed file. The determinism test uses it so it never truncates the
// shared on-disk artifact that other tests read concurrently.
const STDOUT = process.argv.includes("--stdout");

function parse(text) {
  const lines = text.split(/\r?\n/);
  const rows = [];
  let group = null; // current `### calc-*.js (Group X)` heading

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const headingMatch = /^###\s+(calc-[a-z0-9-,. ]*\.js[^\n]*)$/.exec(line);
    if (headingMatch) {
      group = headingMatch[1].trim();
      continue;
    }
    // A per-tile row looks like:
    //   | tile-id | "Citation: ..." |
    // We pick rows whose source-stamp cell starts with a quoted string.
    if (!group) continue;
    if (!line.startsWith("| ")) continue;
    // Skip the header row and the separator row.
    if (line.includes("Tile") && line.includes("Source-stamp")) continue;
    if (/^\|\s*-+\s*\|/.test(line)) continue;
    // Split on `|` but only the first three columns (rest may contain |).
    const parts = splitMarkdownRow(line);
    if (parts.length < 2) continue;
    const tileCell = parts[0].trim();
    const stampCell = parts[1].trim();
    if (!tileCell || !stampCell) continue;
    if (!stampCell.startsWith('"') || !stampCell.endsWith('"')) continue;
    const stamp = stampCell.slice(1, -1);
    // A row may name multiple tiles separated by `, `; emit one entry
    // per tile so the runtime resolution stays per-id.
    const ids = tileCell
      .split(/\s*,\s*/)
      .map((s) => s.trim())
      .filter(Boolean);
    for (const id of ids) {
      rows.push({ id, group, stamp });
    }
  }
  return rows;
}

function splitMarkdownRow(line) {
  // Strip leading/trailing pipe, then split on |. The source-stamp cell
  // never contains a pipe in practice; if a future row does, this will
  // be a parse error caught by the in-sync test (the regenerated file
  // will differ from the committed one).
  const inner = line.replace(/^\|\s*/, "").replace(/\s*\|\s*$/, "");
  return inner.split(/\s*\|\s*/);
}

function buildJson(rows, srcMtime) {
  // De-dup: a tile that appears in two tables is an error per spec
  // (single source of truth). Surface the duplicate as a parse failure.
  const byId = {};
  const dupes = [];
  for (const r of rows) {
    if (byId[r.id]) dupes.push(r.id);
    byId[r.id] = { group: r.group, stamp: r.stamp };
  }
  return {
    _comment:
      "v10 Phase A.3 generated artifact. DO NOT EDIT BY HAND. Source of truth is docs/citation-discipline.md; regenerate via `npm run docs:citation-strings`. Per spec-v10 §3.3 the runtime citations.js will eventually import these strings; the in-sync unit test holds the contract until then.",
    _generated_from: "docs/citation-discipline.md",
    _generator: "scripts/build-citation-strings.mjs",
    _row_count: rows.length,
    _duplicates: dupes,
    strings: byId,
  };
}

// The doc is the source of truth for these strings, and until 2026-09-02 nothing
// compared a row to the string the tile actually prints -- only to the JSON
// generated from the same doc, a copy checked against a copy. 21 of the 70 rows
// had drifted: `dti` documented "per FNMA Single-Family Selling Guide and FHA
// Handbook" while the page printed the section numbers, the 36/45 and 31/43
// thresholds and the VA back-end 41. A reader auditing the site against the doc
// would have been auditing fiction.
//
// So: every row must be the verbatim citation literal of that tile's own
// renderer. Renderer is found through the per-group `"<tile-id>": renderFn`
// dispatch table; the literal is the (possibly `+`-concatenated) string assigned
// to citationEl.textContent inside it.
// Two dispatch shapes ship: a `"tile": renderFn,` row inside the group table,
// and a later `GROUP_RENDERERS["tile"] = renderFn;` assignment for tiles added
// after the table was written. Reading only the first shape silently skipped
// 16 tiles, which would have made this gate report drift it could not see.
const RENDER_ENTRY = /(?:"([a-z0-9-]+)":|\[\s*"([a-z0-9-]+)"\s*\]\s*=)\s*(_?[A-Za-z0-9_]*[Rr]ender[A-Za-z0-9_]*)\s*[,;]/g;
const CITATION_ASSIGN = /citationEl\.textContent\s*=\s*((?:"(?:[^"\\]|\\.)*"\s*(?:\+\s*)?)+);/;
const STRING_PART = /"((?:[^"\\]|\\.)*)"/g;

async function rendererCitations() {
  const byTile = new Map();
  const files = (await readdir(ROOT)).filter((f) => /^calc-.*\.js$/.test(f)).sort();
  for (const f of files) {
    const src = await readFile(resolve(ROOT, f), "utf8");
    for (const m of src.matchAll(RENDER_ENTRY)) {
      const tile = m[1] || m[2];
      if (byTile.has(tile)) continue;
      const at = src.indexOf("function " + m[3]);
      if (at < 0) continue;
      const body = src.slice(at, at + 4000);
      const c = body.match(CITATION_ASSIGN);
      if (!c) continue;
      let s = "";
      for (const part of c[1].matchAll(STRING_PART)) s += part[1];
      byTile.set(tile, s.replace(/\\"/g, '"'));
    }
  }
  return byTile;
}

async function main() {
  if (!existsSync(SRC)) {
    console.error("ERROR: " + SRC + " not found.");
    process.exit(1);
  }
  const text = await readFile(SRC, "utf8");
  const rows = parse(text);
  if (rows.length === 0) {
    console.error("ERROR: parsed zero rows from citation-discipline.md.");
    process.exit(1);
  }
  const json = buildJson(rows);
  if (json._duplicates.length > 0) {
    console.error(
      "ERROR: duplicate tile id(s) in citation-discipline.md: " + json._duplicates.join(", "),
    );
    process.exit(1);
  }
  // Stable sort key order so the on-disk JSON is deterministic.
  const sortedStrings = {};
  for (const id of Object.keys(json.strings).sort()) {
    sortedStrings[id] = json.strings[id];
  }
  json.strings = sortedStrings;
  const out = JSON.stringify(json, null, 2) + "\n";

  if (MODE === "check") {
    const printed = await rendererCitations();
    const drift = [];
    for (const row of rows) {
      const live = printed.get(row.id);
      if (live === undefined) {
        drift.push(row.id + ": no citation literal found in its renderer");
      } else if (live !== row.stamp) {
        drift.push(
          row.id + ": the doc and the page disagree\n      doc:  " + row.stamp.slice(0, 120) +
            "\n      page: " + live.slice(0, 120),
        );
      }
    }
    if (drift.length > 0) {
      for (const d of drift) console.error("ERROR: " + d);
      console.error(
        "ERROR: " + drift.length + " of " + rows.length + " row(s) in docs/citation-discipline.md do not match\n" +
          "  the citation the tile prints. The doc is the source of truth for the wording, so change the\n" +
          "  renderer to match it, or update the row and rerun `npm run docs:citation-strings`.",
      );
      process.exit(1);
    }
    if (!existsSync(OUT)) {
      console.error("ERROR: " + OUT + " missing. Run `npm run docs:citation-strings`.");
      process.exit(1);
    }
    const onDisk = await readFile(OUT, "utf8");
    if (onDisk !== out) {
      console.error(
        "ERROR: " + OUT + " is out of sync with docs/citation-discipline.md. Run `npm run docs:citation-strings`.",
      );
      process.exit(1);
    }
    console.log(
      "v10 citation-strings in-sync OK (" + rows.length + " rows / " + Object.keys(sortedStrings).length +
        " tiles; every row is the verbatim citation its renderer prints).",
    );
    return;
  }

  if (STDOUT) {
    process.stdout.write(out);
    return;
  }

  await writeFile(OUT, out);
  console.log(
    "wrote " + OUT + " (" + rows.length + " rows / " + Object.keys(sortedStrings).length + " tiles).",
  );
}

await main();
